def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    events = {}

    # A gap bracketed by the same color in a horizontal stripe marks
    # a vertical segment of that color.
    for r in range(h):
        if sum(v != 0 for v in grid[r]) < 3:
            continue
        c = 0
        while c < w:
            if grid[r][c] != 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 0:
                c += 1
            if start > 0 and c < w and grid[r][start - 1] == grid[r][c]:
                color = grid[r][start - 1]
                for x in range(start, c):
                    out[r][x] = color
                    events.setdefault(x, []).append((r, color))

    # Fill each marked column between successive horizontal gaps.
    # The existing vertical stem below the last gap supplies the final color.
    for c, marks in events.items():
        marks.sort()
        previous = -1
        for r, color in marks:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r

        stem_color = next(
            (grid[rr][c] for rr in range(previous + 1, h) if grid[rr][c] != 0),
            None
        )
        if stem_color is not None:
            for rr in range(previous + 1, h):
                out[rr][c] = stem_color

    return out
